#!/bin/bash
# Copyright (c) 2026 Jean-Philippe Meunier
# SPDX-License-Identifier: Apache-2.0
# Assembles the standalone iOS project for the Feedback report: BarrierRepro.mm, the app and the README, with the Xcode
# project generated by XcodeGen, so that it opens without XcodeGen. It checks that the project builds for iOS, unsigned,
# then zips it without build products.
# Usage: package-feedback.sh <output directory>
set -euo pipefail
here=$(cd "$(dirname "$0")" && pwd)
output=$(mkdir -p "${1:?output directory}" && cd "$1" && pwd)
package=$output/BarrierRepro
rm -rf "$package" "$output/BarrierRepro.zip" && mkdir -p "$package"
cp -R "$here/Feedback/." "$package/"
cp "$here/BarrierRepro.mm" "$package/App/"
xcodegen generate --spec "$package/project.yml" --project "$package"
xcodebuild -project "$package/BarrierRepro.xcodeproj" -scheme BarrierRepro -configuration Release -destination 'generic/platform=iOS' \
	-derivedDataPath "$output/DerivedData" CODE_SIGNING_ALLOWED=NO build > "$output/build.log" 2>&1 || { tail -20 "$output/build.log"; exit 1; }
(cd "$output" && ditto -c -k --norsrc --noextattr --noqtn --keepParent BarrierRepro BarrierRepro.zip)
(cd "$output" && shasum -a 256 BarrierRepro.zip BarrierRepro/App/BarrierRepro.mm BarrierRepro/App/main.mm > SHA256SUMS)
echo "FEEDBACK PACKAGE: $output/BarrierRepro.zip"
